 TransferShapeBinder Edit(Shape shape,int index,int action){ArgumentNullException.ThrowIfNull(shape);NativeError.ThrowIfFailed(EditNative(NativeHandle,index,shape.Handle,null,action,out var p),"transfer_binder_edit");return new(p);}
 /// <summary>Creates an independent binder with a copied failure or warning message.</summary>
 public TransferShapeBinder WithMessage(string message,bool warning=false){TransferRecordInterop.TextInput(message);NativeError.ThrowIfFailed(MessageNative(NativeHandle,0,0,message,warning?3:2,out var p),"transfer_binder_message");return new(p);}
 /// <summary>Returns independent ordered shape storage.</summary>
 public OwnedShapeSet Shapes {get{NativeError.ThrowIfFailed(ShapesNative(NativeHandle,out var p),"transfer_binder_shapes");return new(p);}}
 /// <summary>Gets a zero-based shape, optionally requiring an exact topology kind.</summary>
 public Shape GetShape(int index,ShapeKind kind=ShapeKind.Shape){NativeError.ThrowIfFailed(ShapeNative(NativeHandle,index,(int)kind,out var p),"transfer_binder_shape");return ShapeFactory.FromNativeHandle(p,"transfer_binder_shape");}
 /// <summary>Copies the current native status and diagnostic text.</summary>
 public TransferBinderState State {get{NativeError.ThrowIfFailed(SnapshotNative(NativeHandle,out var p),"transfer_binder_snapshot");using var owner=TransferRecordInterop.Own(p,1);using var doc=TransferRecordInterop.Text(owner);var item=doc.RootElement;return new(item.GetProperty("HasResult").GetBoolean(),item.GetProperty("Status").GetInt32(),item.GetProperty("ResultType").GetString()!,TransferRecordInterop.Messages(item));}}
 /// <summary>Releases this binder; derived binders and copied shapes remain usable.</summary>
 public void Dispose()=>handle.Dispose();
